Producer consumer using wait and notify:





import java.util.*;



class SharedBuffer {



    private Queue<Integer> queue = new LinkedList<>();

    private int capacity;



    SharedBuffer(int capacity) {

        this.capacity = capacity;

    }



    public synchronized void produce(int value) throws InterruptedException {



        while (queue.size() == capacity) {

            wait();   // buffer full

        }



        queue.add(value);

        System.out.println("Produced: " + value);



        notify();  // wake consumer

    }



    public synchronized void consume() throws InterruptedException {



        while (queue.isEmpty()) {

            wait();   // buffer empty

        }



        int value = queue.poll();

        System.out.println("Consumed: " + value);



        notify();  // wake producer

    }

}



public class Main {

    public static void main(String[] args) {

        SharedBuffer buffer = new SharedBuffer(5);



        Thread producer = new Thread(() -> {

            int value = 1;

            try {

                while (true) {

                    buffer.produce(value++);

                    Thread.sleep(500);

                }

            } catch (InterruptedException e) {}

        });



    Thread consumer = new Thread(() -> {

            try {

                while (true) {

                    buffer.consume();

                    Thread.sleep(800);

                }

            } catch (InterruptedException e) {}

        });



        producer.start();

        consumer.start();

    }

}

Read–Write Lock Problem:

Read–Write Lock Problem:

Problem

Multiple threads can read simultaneously

Only one thread can write at a time

No read during write

No write during read 



Key Concept

Use ReentrantReadWriteLock

readLock() → shared lock

writeLock() → exclusive lock










import java.util.concurrent.locks.*;



class SharedResource {



    private int data = 0;



    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();



    // READ operation

    public void read() {

        lock.readLock().lock();

        try {

            System.out.println(Thread.currentThread().getName() +

                    " reading value: " + data);



            Thread.sleep(100); // simulate read delay

        } catch (InterruptedException e) {

            e.printStackTrace();

        } finally {

            lock.readLock().unlock();

        }

    }



    // WRITE operation

    public void write(int value) {

        lock.writeLock().lock();

        try {

            System.out.println(Thread.currentThread().getName() +

                    " writing value: " + value);



            Thread.sleep(100); // simulate write delay

            data = value;



        } catch (InterruptedException e) {

            e.printStackTrace();

        } finally {

            lock.writeLock().unlock();

        }

    }

}



public class Main {



    public static void main(String[] args) {



        SharedResource resource = new SharedResource();



        // Reader threads

        Runnable reader = () -> {

            for (int i = 0; i < 3; i++) {

                resource.read();

            }

        };



        // Writer thread

        Runnable writer = () -> {

            for (int i = 1; i <= 3; i++) {

                resource.write(i * 10);

            }

        };



        Thread r1 = new Thread(reader, "Reader-1");

        Thread r2 = new Thread(reader, "Reader-2");

        Thread w1 = new Thread(writer, "Writer-1");



        r1.start();

        r2.start();

        w1.start();

    }

}



Dining Philosopher Problem

Dining Philosopher Problem:







import java.util.concurrent.Semaphore;



class DiningPhilosophers {



private final Semaphore table = new Semaphore(4);

private final Semaphore[] forks = new Semaphore[5];





    public DiningPhilosophers() {

        for (int i = 0; i < 5; i++) {

            forks[i] = new Semaphore(1);

        }

    }



    public void wantsToEat(int id) throws InterruptedException {



        int left = id;

        int right = (id + 1) % 5;



        table.acquire();



        forks[left].acquire();

        forks[right].acquire();



        eat(id);



        forks[left].release();

        forks[right].release();



        table.release();

    }



    private void eat(int id) {

        System.out.println("Philosopher " + id + " is eating");

    }

}





public class Main {



    public static void main(String[] args) {



        DiningPhilosophers dp = new DiningPhilosophers();



        for (int i = 0; i < 5; i++) {

            int id = i;

            new Thread(() -> {

                try {

                    dp.wantsToEat(id);

                } catch (InterruptedException e) {

                    Thread.currentThread().interrupt();

                }

            }).start();

        }

    }

}












