Avoid Deadlock :



Always acquire locks in same order





class Resource {

    private final String name;



    public Resource(String name) {

        this.name = name;

    }



    public String getName() {

        return name;

    }

}





public class DeadlockFixed {



    public static void main(String[] args) {



        Resource r1 = new Resource("R1");

        Resource r2 = new Resource("R2");



        Thread t1 = new Thread(() -> lockInOrder(r1, r2));

        Thread t2 = new Thread(() -> lockInOrder(r1, r2)); // same order



        t1.start();

        t2.start();

    }



    public static void lockInOrder(Resource r1, Resource r2) {

        synchronized (r1) {

            System.out.println(Thread.currentThread().getName() + " locked " + r1.getName());



            try { Thread.sleep(100); } catch (InterruptedException e) {}



